// 1. Primitive Type Initialization
int x {10};
int y {};     // Zero initialization (0)

// 2. Array Initialization
int arr[] {1, 2, 3, 4};

// 3. Aggregate Initialization (Struct/Class without custom ctor)
struct Item { int id; double price; };
Item item {101, 19.99};

// 4. Initialization using std::initializer_list
std::vector<std::string> names {"Alice", "Bob", "Charlie"};

// 5. Narrowing Conversion Prevention (Safety feature)
long big = 1000000;
// int fail {big};     // Compile Error: long to int narrowing
int ok = (int)big;     // Explicit cast works
int ok_safe {10};      // Non-narrowing is fine
// int fail_float {5.5}; // Compile Error: double to int narrowing
